INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('joshi-kausei','Joshi Kausei','女子かう生',2019,5.8,'Spring 2019','TV','Finished','https://media.kitsu.app/anime/poster_images/41941/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/104147-cUQyefM82UfY.jpg','#2f7bff','A silent high school girl anime that''s still cute, even if no one talks! This is a story about three girls and their fun high school life, centering around the unfortunate beauty, Momoko, the cool girl with glasses, Shibumi, and the gentle little Mayumi. Fun alone, fun with all. The daily lives of slightly dumb yet cute high school girls. (Source: Crunchyroll)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":41941,"anilist":104147,"mal":38295}',NULL,NULL,12,datetime('now'),'joshi kausei 女子かう生 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('afterlost','AFTERLOST','消滅都市',2019,5.4,'Spring 2019','TV','Finished','https://media.kitsu.app/anime/poster_images/41451/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/101814-ZGxZDetD2Lpp.jpg','#2ee6a8','The entire population of a city disappeared—vanished without a trace. Yuki, the sole survivor, joins Takuya, a contract courier, on a perilous journey to find answers within the newly named ghost town “Lost”. With a letter from Yuki’s father as the pair’s only lead, a secretive organization refuses to let Yuki and Takuya’s meddling go unchecked. (Source: Funimation)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":41451,"anilist":101814,"mal":37952}',NULL,NULL,12,datetime('now'),'afterlost 消滅都市 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('fuuto-pi','Fuuto PI','風都探偵',2022,7.2,'Summer 2022','TV','Finished','https://media.kitsu.app/anime/44323/poster_image/medium-10130e606a36f76c7a7765a8c3f95afa.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/131912-YPKK1NQel4Yd.jpg','#ffc247','In the ecologically-minded city of Fuuto, mysterious devices resembling USB flash drives called Gaia Memories are used by criminals and other interested parties to become monsters called Dopants, committing crimes with the police force powerless to stop them. To make matters worse, the Gaia Memories carry a dangerous toxin that cause their users to go insane to the point where they could die from the life-threatening devices. After the death of his boss, the self-proclaimed hard-boiled detective Shoutaro Hidari works with the mysterious Philip to investigate crimes which involve Dopants. Using their own Gaia Memories, Shoutaro and Philip use the Double Driver belts to transform and combine into Kamen Rider Double to fight the Dopant menace and keep Fuuto safe. (Source: Anilist)',NULL,'["Fuuto PI: The Portrait of Kamen Rider Skull (2024)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":44323,"anilist":131912,"mal":48649}',48649,'mal',12,datetime('now'),'fuuto pi 風都探偵 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
