INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('wu-shan-wu-xing-zhuo-yuan-shen-huo','Wu Shan Wu Xing: Zhuo Yuan Shen Huo','雾山五行 灼源神火',2020,7.8,'','TV','Finished','https://media.kitsu.app/anime/poster_images/41361/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/107069-tjm6yI8kud5D.jpg','#ff3d8b','A legend tells that a long time ago, monsters could give the ability to certain elected officials to master the five elements. But for that, you have to go through the dangerous foggy mountains... We follow the adventures of one of these elected officials. (Source: Nautiljon) An original animation series created by Samsara Studio and co-produced by Nice Boat Animation. The first three episode will come out in 2020. Due to the small size of the studio, the series will be updated irregularly.',NULL,'["Wu Shan Wu Xing: Xi Chuan Huan Zi Lin","Wu Shan Wu Xing"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":41361,"anilist":107069,"mal":37936}',NULL,NULL,3,datetime('now'),'wu shan wu xing zhuo yuan shen huo 雾山五行 灼源神火 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=