INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('fate-grand-order-moonlight-lostroom','Fate/Grand Order -MOONLIGHT/LOSTROOM-','Fate/Grand Order -MOONLIGHT/LOSTROOM-',2017,6.4,'Fall 2017','Special','Finished','https://media.kitsu.app/anime/14096/poster_image/medium-9fe9463dda82cd37231a275ea0c20332.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/100728-k33qsytFb8ik.jpg','#2ee6a8','The Lost Room. A place where you can see what was lost, or maybe what will be lost to you in time. Existing in the innermost part of Chaldea, it is the boundary line between dream and reality where the light of the moon shines through. Produced by the Chaldea Summoning System, the room holds a small number of worthwhile benefits to enjoy. (Source: Crunchyroll)',NULL,'["Fate/Grand Order Final Singularity - Grand Temple of Time: Solomon (2021)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":14096,"anilist":100728,"mal":36915}',NULL,NULL,1,datetime('now'),'fate grand order moonlight lostroom fate grand order moonlight lostroom special finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=exclu