INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('afro-samurai-resurrection','Afro Samurai: Resurrection','アフロサムライ：レザレクション',2009,7.2,'Winter 2009','Movie','Finished','https://media.kitsu.app/anime/poster_images/3870/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/4970-Z2RkL6I35hLN.jpg','#ffc247','Takashi Okazaki said in the new season Afro "loses his way, gets tired of all the killing" and he "wakes up to his destiny, which is to be the world''s number one warrior". Produced by Japanese studio GONZO in association/partnership with GDH K.K. and based on the original art and story telling of manga artist Takashi Okazaki. Funimation is also collaborating on the production.',NULL,'["Afro Samurai the Movie (2007)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":3870,"anilist":4970,"mal":4970}',NULL,NULL,1,datetime('now'),'afro samurai resurrection アフロサムライ レサ レクション movie finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;

