INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#1','joshi-kausei',1,'The High School Girl and Thighs','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261174/original.jpg','High school girl Futo Momoko is napping in the classroom when her best friends Furui Mayumi and Shibusawa Shibumi drop in. Later, when Momoko is relaxing alone, a mosquito flies into the room...','[]','2019-04-06','261174');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#2','joshi-kausei',2,'The High School Girl and the Unlucky Day','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261175/original.jpg','Momoko is watching TV before school, and the morning horoscope says that her sign will have the worst luck today. Despite her dread, Momoko leaves for school, and one bad thing after another threatens to ruin her day.','[]','2019-04-13','261175');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#3','joshi-kausei',3,'The High School Girl and Drowsiness','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261176/original.jpg','Fukuouda Tadashi boards his train very sleepy, but seated in front of where he''s standing is Momoko. He tries to make himself look cool, but epically fails. To add insult to injury, he unwraps a stick of gum, but then drops it right between Momoko''s thighs...','[]','2019-04-20','261176');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#4','joshi-kausei',4,'The High School Girl and the Family Restaurant','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261177/original.jpg','Momoko, Shibumi, and Mayumi are at a family restaurant. Momoko is out of money, so she can only watch while the other two eat. She ends up occupying herself by making animals out of the restaurant napkins.','[]','2019-04-27','261177');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#5','joshi-kausei',5,'The High School Girl and the Skateboard','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261178/original.jpg','','[]','2019-05-04','261178');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#6','joshi-kausei',6,'The High School Girl and Working Out','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261179/original.jpg','Momoko''s sister, Kizuku, sees a special on TV about a weight loss routine and suddenly feels that there''s too much fat around her belly. So she tries to do the exercises they did on TV...','[]','2019-05-11','261179');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#7','joshi-kausei',7,'The High School Girl and the Foggy Window','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261180/original.jpg','On a snowy day, Momoku, Shibumi, and Mayumi start to breathe on the classroom window glass and draw in the fog with their fingers. Their drawings quickly disappear, but later, when steam from a teapot fills the room...','[]','2019-05-18','261180');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#8','joshi-kausei',8,'The High School Girl and Hiding from the Rain','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261181/original.jpg','Fukoda is taking shelter from the rain in a bus stop, when Momoko comes along and takes cover under the same shelter. As he sees Momoko''s wet shirt and the way she ties up her hair, Fukoda starts to feel rather tense...','[]','2019-05-25','261181');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#9','joshi-kausei',9,'The High School Girl and Shadow Puppets','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261182/original.jpg','','[]','2019-06-01','261182');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('joshi-kausei#10','joshi-kausei',10,'The High School Girl and the Hair Barrette','3:00',180,'https://media.kitsu.app/episodes/thumbnails/261183/original.jpg','','[]','2019-06-08','261183');
