INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#1','afterlost',1,'Lost','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247601/original.jpg','One day, a certain city completely disappears from the map. Three years later, a lone courier named Takuya saves Yuki, the lone survivor of Lost, and the two begin their journey to the void that was once a city.','[]','2019-04-07','247601');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#2','afterlost',2,'Sacrifice','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247602/original.jpg','After Takuya gets severely injured by a mysterious boy, it is decided that going straight to Lost is too dangerous. Yuki and the others try to escape, but Suzuna and the Agency interferes. And so does a dangerous knife-wielding Tama-shi.','[]','2019-04-14','247602');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#3','afterlost',3,'Memory','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247603/original.jpg','Takuya, Yuki, and Geek get stuck in a strange pocket of space near Lost. Worried about Yumiko and Kouta, they look for a way out. But Geek comes across something he cannot believe. The members of SPR5, including Yua, appear right before his eyes.','[]','2019-04-21','247603');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#4','afterlost',4,'Suspicion','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247604/original.jpg','Takuya is sent to ICU and Yuki is traumatized from hurting her little brother. Unbeknownst to them, various people have started taking action. Some have appeared to help. To find the truth. While others work to keep the plans of the Agency moving forward.','[]','2019-04-28','247604');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#5','afterlost',5,'Affection','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247605/original.jpg','With the recent discovery of Tsuki''s Tears, the famous magician Yoshiaki appears before Takuya. He asks for help in capturing Tsubasa, leader of the phantom thief brigade X. With doubts in their heart, Yoshiaki and Yuki both chase after their family.','[]','2019-05-05','247605');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#6','afterlost',6,'Parting Ways','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247606/original.jpg','Yuki fights with Souma in hopes of bringing him back to his senses. However, sometimes it is hard to understand the true feelings of your siblings. Just when they think they''ve cornered Souma, he summons and attacks with Tsubasa.','[]','2019-05-12','247606');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#7','afterlost',7,'Regret','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247607/original.jpg','Takuya comes into contact with his past, a failed mission at the Light of Hope Academy for Disabled Children. As they step inside, Takuya and the others fall into another pocket of space. They have one goal, find evidence to bring down Lacuna.','[]','2019-05-19','247607');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#8','afterlost',8,'Choice','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247608/original.jpg','Takuya and the others have decided to infiltrate Lacuna Chemical Laboratory, in order to drag the Agency out into the open. With the help of Yoshiaki, they use public media to draw attention to the company''s wrongdoings and spur the police to move.','[]','2019-05-26','247608');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#9','afterlost',9,'Fate','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247609/original.jpg','Amongst the volunteers, only Daichi, Taiyo, and Tsuki survive. The three of them begin working on Project Noah, in order to save millions of their people. As Daichi continues his research, he meets a woman named Miyuki and begins to question his actions.','[]','2019-06-02','247609');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#10','afterlost',10,'Decision','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247610/original.jpg','Yuki and Takuya have to make a choice. Eiji and Kikyo try to stop the two of them from going to Lost, by telling them the true dangers of the place. While, Taiyo has begun to move into the final stages of his plan to complete the portal.','[]','2019-06-09','247610');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#11','afterlost',11,'Trust','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247611/original.jpg','With help of their allies, Yuki and Takuya manage to enter Lost. As soon as they enter, they fall in a whirlpool of their own memories. The voices of their friends and their bond to each other are the only things that can keep them moving forward.','[]','2019-06-16','247611');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('afterlost#12','afterlost',12,'Future','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/247612/original.jpg','Takuya and Yuki manage to keep themselves together as they enter Lost. They find Taiyo trying to eliminate Yuki''s father, Daichi. As Daichi fights back, he reveals to Yuki that he had prepared everything for her and that she must now make a choice.','[]','2019-06-23','247612');
